//! C++ bindings for the `quickik` crate, generated by
//! [Diplomat](https://github.com/rust-diplomat/diplomat) from the `ffi` bridge
//! module in each file here (see `build.rs`). Types, methods and argument names
//! mirror the Rust API, so the same program reads almost the same in both
//! languages. C++-specific differences:
//!
//! - Every type lives in namespace `quickik`. Opaque types (everything but the
//!   small math structs in `geometry.rs`) are created with static functions
//!   (`create`, or named like the Rust constructor) and owned via
//!   `std::unique_ptr`.
//! - Fallible functions return a `diplomat::result` holding the value or a
//!   `quickik::Error`. `quickik::unwrap` (in `include/quickik.hpp`) turns it
//!   into the value or a thrown `quickik::Exception`.
//! - Arrays are passed and returned as flat, row-major `float` spans, e.g.
//!   keypoint positions as `n_joints * 3` floats.
//! - Lists that Diplomat can't pass across (nested vectors, vectors of
//!   observations) have their own types: `KeypointObservationList` for one
//!   frame's observations, and `SolverResultList` for per-frame results.

// Diplomat needs every borrowed return value's lifetime spelled out.
#![allow(clippy::needless_lifetimes)]

mod body_plan;
mod error;
mod forward;
mod geometry;
mod observation;
mod sequential_solver;
mod solver;
mod state;
